/* ---------- drawing helpers for this lesson (prefixed CT_ so they never clash with engine globals) ---------- */
const CT_F='font-family="Nunito Sans, sans-serif"';
const CT_INK='#18213A', CT_MUT='#5C6577', CT_AX='#ADB5BD';
const CT_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${CT_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||CT_INK}"${o.it?' font-style="italic"':''}>${t}</text>`;
const CT_L=(x1,y1,x2,y2,col=CT_MUT,w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const CT_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"/>`;
const CT_poly=(P,col,w=4,ex='')=>`<polyline points="${P.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
const CT_arrow=(x1,y1,x2,y2,col=CT_INK,w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return CT_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const CT_sub=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
const CT_sup=(a,b)=>`${a}<tspan baseline-shift="super" font-size="70%">${b}</tspan>`;
const CT_dot=(x,y,col=CT_INK,r=6)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${col}"/>`;
const CT_x=(x,y,col,s=9,w=4)=>CT_L(x-s,y-s,x+s,y+s,col,w)+CT_L(x-s,y+s,x+s,y-s,col,w);
/* a curve of computed points f(t), t in [t0,t1] mapped to x in [x0,x1], y = yc - k*f */
const CT_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=160,ex='')=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push([x0+(x1-x0)*i/n,yc-k*f(t)])}return CT_poly(p,col,w,ex)};
/* circuit symbols (leads included) */
const CT_res=(x1,x2,y,col=CT_INK,w=3)=>{const m=(x1+x2)/2,a=m-42,s=84/6;let p=[[x1,y],[a,y]];for(let i=0;i<6;i++)p.push([a+s*(i+.5),y+(i%2?12:-12)]);p.push([m+42,y],[x2,y]);return CT_poly(p,col,w)};
const CT_resV=(x,y1,y2,col=CT_INK,w=3)=>{const m=(y1+y2)/2,a=m-42,s=84/6;let p=[[x,y1],[x,a]];for(let i=0;i<6;i++)p.push([x+(i%2?12:-12),a+s*(i+.5)]);p.push([x,m+42],[x,y2]);return CT_poly(p,col,w)};
const CT_coil=(x1,x2,y,col=CT_INK,w=3)=>{const m=(x1+x2)/2,a=m-44;let d=`M${x1} ${y}L${a} ${y}`;for(let i=0;i<4;i++)d+=`A11 11 0 0 1 ${a+22*(i+1)} ${y}`;d+=`L${x2} ${y}`;return `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/>`};
const CT_coilV=(x,y1,y2,col=CT_INK,w=3)=>{const m=(y1+y2)/2,a=m-44;let d=`M${x} ${y1}L${x} ${a}`;for(let i=0;i<4;i++)d+=`A11 11 0 0 1 ${x} ${a+22*(i+1)}`;d+=`L${x} ${y2}`;return `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/>`};
const CT_cap=(x1,x2,y,col=CT_INK,w=3)=>{const m=(x1+x2)/2;return CT_L(x1,y,m-8,y,col,w)+CT_L(m+8,y,x2,y,col,w)+CT_L(m-8,y-22,m-8,y+22,col,w+2)+CT_L(m+8,y-22,m+8,y+22,col,w+2)};
const CT_capV=(x,y1,y2,col=CT_INK,w=3)=>{const m=(y1+y2)/2;return CT_L(x,y1,x,m-8,col,w)+CT_L(x,m+8,x,y2,col,w)+CT_L(x-22,m-8,x+22,m-8,col,w+2)+CT_L(x-22,m+8,x+22,m+8,col,w+2)};
const CT_vs=(cx,cy,r=30,col=ORG)=>`<circle cx="${cx}" cy="${cy}" r="${r}" fill="#FFFFFF" stroke="${col}" stroke-width="4"/>`+CT_T(cx,cy-r*.22,'+',{fs:r*.9,fw:800,a:'middle',fill:col})+CT_T(cx,cy+r*.72,'−',{fs:r*.9,fw:800,a:'middle',fill:col});
const CT_ac=(cx,cy,r=30,col=ORG)=>`<circle cx="${cx}" cy="${cy}" r="${r}" fill="#FFFFFF" stroke="${col}" stroke-width="4"/>`+CT_curve(t=>Math.sin(t),0,2*Math.PI,cx-r*.6,cx+r*.6,cy,r*.32,col,3,40);
/* a series R-L-C loop with a source on the left, drawn in a 350 × 140 frame at (ox,oy), scale s */
const CT_ser=(ox,oy,s=1,o={})=>`<g transform="translate(${ox} ${oy}) scale(${s})">${(o.ac?CT_ac:CT_vs)(36,72,26)}${CT_L(36,46,36,16,CT_INK,3)}${CT_L(36,16,70,16,CT_INK,3)}${CT_res(70,170,16,o.rc||CT_INK)}${o.noL?CT_L(170,16,300,16,CT_INK,3):CT_coil(170,270,16)+CT_L(270,16,300,16,CT_INK,3)}${o.noC?CT_L(300,16,300,128,CT_INK,3):CT_capV(300,16,128)}${CT_L(300,128,36,128,CT_INK,3)}${CT_L(36,98,36,128,CT_INK,3)}${CT_T(120,56,'R',{fs:26,fw:800,a:'middle',fill:o.rc||CT_INK,it:1})}${o.noL?'':CT_T(220,56,'L',{fs:26,fw:800,a:'middle',it:1})}${o.noC?'':CT_T(334,80,'C',{fs:26,fw:800,it:1})}</g>`;
/* the step responses of the first worked example (L = 1 H, C = 0.01 F, 10 V step, nothing stored), in volts, t in s */
const CT_wd1=Math.sqrt(96);
const CT_vu=t=>10-Math.exp(-2*t)*(10*Math.cos(CT_wd1*t)+(20/CT_wd1)*Math.sin(CT_wd1*t));   // R = 4 Ω: peak 15.27 V at 0.321 s
const CT_vcr=t=>10-10*(1+10*t)*Math.exp(-10*t);                                           // R = 20 Ω: s = −10 twice
const CT_s1=-20+Math.sqrt(300), CT_s2=-20-Math.sqrt(300);                                   // R = 40 Ω: s = −2.68, −37.32
const CT_vo=t=>10+(-10*CT_s2/(CT_s2-CT_s1))*Math.exp(CT_s1*t)+(10*CT_s1/(CT_s2-CT_s1))*Math.exp(CT_s2*t);
/* the 5.5 example: ζ = 0.1, ωₙ = 1000 rad/s, unit step; t in ms */
const CT_wd2=1000*Math.sqrt(0.99);
const CT_y2=tm=>{const t=tm/1000;return 1-Math.exp(-100*t)*(Math.cos(CT_wd2*t)+(100/CT_wd2)*Math.sin(CT_wd2*t))};
/* the 5.6 example: R = 4 Ω, L = 1 H, vs = 10 sin 3t V, i(0) = 0 */
const CT_th=Math.atan2(3,4);
const CT_iss=t=>2*Math.sin(3*t-CT_th), CT_off=t=>1.2*Math.exp(-4*t), CT_itot=t=>CT_iss(t)+CT_off(t);
