function EXTRA(R,ICON){
 /* hook: the circuit, and its capacitor voltage ringing up to 15.27 V before settling at 10 V (computed from the first worked example) */
 ICON.ctHookA=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${CT_box(0,0,380,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${CT_T(20,34,'10 V step into R, L and C',{fs:22,fw:800,fill:BLU})}${CT_ser(14,42,.92)}</g>`;
 ICON.ctHookB=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${CT_box(0,0,380,170,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${CT_T(20,32,'capacitor voltage',{fs:22,fw:800,fill:ORG})}${CT_L(20,156,360,156,CT_AX,2)}${CT_L(20,91,360,91,CT_AX,2,'stroke-dasharray="6 5"')}${CT_curve(CT_vu,0,2,20,360,156,6.5,ORG,4)}${CT_dot(20+340*0.3206/2,156-6.5*15.27,ORG,6)}${CT_T(112,66,'15.27 V',{fs:22,fw:800,fill:ORG})}${CT_T(360,84,'10 V',{fs:22,fw:800,a:'end',fill:CT_MUT})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.ctCases=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_T(10,30,'under',{fs:26,fw:800,fill:BLU})}${CT_T(130,30,'critical',{fs:26,fw:800,fill:ORG})}${CT_T(290,30,'over',{fs:26,fw:800,fill:GRN})}${CT_L(10,310,410,310,CT_AX,2)}${CT_curve(CT_vo,0,2,10,410,310,15,GRN,5)}${CT_curve(CT_vcr,0,2,10,410,310,15,ORG,5)}${CT_curve(CT_vu,0,2,10,410,310,15,BLU,5)}</g>`;
 ICON.ctPoles=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_L(60,175,410,175,CT_AX,2)}${CT_L(350,320,350,30,CT_AX,2)}<path d="M350 35 A140 140 0 0 0 350 315" fill="none" stroke="${CT_AX}" stroke-width="3" stroke-dasharray="7 6"/>${CT_x(336,36,BLU,11,5)}${CT_x(336,314,BLU,11,5)}${CT_x(266,63,ORG,11,5)}${CT_x(266,287,ORG,11,5)}${CT_x(210,175,GRN,11,5)}${CT_T(20,40,'ζ = 0.1',{fs:26,fw:800,fill:BLU})}${CT_T(20,90,'ζ = 0.6',{fs:26,fw:800,fill:ORG})}${CT_T(20,150,'ζ = 1',{fs:26,fw:800,fill:GRN})}</g>`;
 ICON.ctOffset=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_T(10,30,'sine',{fs:26,fw:800,fill:ORG})}${CT_T(110,30,'offset',{fs:26,fw:800,fill:GRN})}${CT_T(240,30,'total',{fs:26,fw:800,fill:BLU})}${CT_L(10,190,410,190,CT_AX,2)}${CT_curve(CT_iss,0,2.5,10,410,190,60,ORG,4,160,'stroke-dasharray="8 6"')}${CT_curve(CT_off,0,2.5,10,410,190,60,GRN,4)}${CT_curve(CT_itot,0,2.5,10,410,190,60,BLU,5)}</g>`;
}
